def _seed_from_history() -> None:
    """One template per workout name done at least 3 times, copied from its latest workout that has sets (E18)."""
    bind = op.get_bind()
    names = bind.execute(
        sa.text(
            "SELECT w.name FROM workouts w WHERE EXISTS (SELECT 1 FROM workout_sets s WHERE s.workout_id = w.id)"
            " GROUP BY w.name HAVING count(*) >= 3 ORDER BY max(w.started_at) DESC"
        )
    ).scalars()
    for position, name in enumerate(names.all()):
        latest = bind.execute(
            sa.text(
                "SELECT w.id FROM workouts w WHERE w.name = :name"
                " AND EXISTS (SELECT 1 FROM workout_sets s WHERE s.workout_id = w.id)"
                " ORDER BY w.started_at DESC LIMIT 1"
            ),
            {"name": name},
        ).scalar_one()
        rows = bind.execute(
            sa.text(
                "SELECT exercise_id, exercise_order, set_type, weight_kg, reps FROM workout_sets"
                " WHERE workout_id = :id AND completed ORDER BY exercise_order, set_order"
            ),
            {"id": latest},
        ).all()
        exercises: list[dict] = []
        for exercise_id, _, set_type, weight_kg, reps in rows:
            if not exercises or exercises[-1]["exercise_id"] != exercise_id:
                exercises.append({"exercise_id": exercise_id, "sets": []})
            exercises[-1]["sets"].append({"set_type": set_type, "weight_kg": weight_kg, "reps": reps})
        if exercises:
            bind.execute(
                sa.text(
                    "INSERT INTO workout_templates (id, name, position, exercises, updated_at)"
                    " VALUES (gen_random_uuid(), :name, :position, CAST(:exercises AS jsonb), now())"
                ),
                {"name": name, "position": position, "exercises": json.dumps(exercises)},
            )


